# AUTOGENERATED! DO NOT EDIT!

from pathlib import Path
import asyncio

from .._utils.sync_helper import SyncSetting
from ..config import get_config
from .._utils.locking import BoxyardLockManager, LockAcquisitionError, BOX_SYNC_LOCK_TIMEOUT, acquire_lock_async

async def exclude_box(
    config_path: Path,
    box_index_name: str,
    skip_sync: bool = False,
    soft_interruption_enabled: bool = True,
):
    """ """
    config = get_config(config_path)
    from boxyard._models import get_boxyard_meta
    
    boxyard_meta = get_boxyard_meta(config)
    
    if box_index_name not in boxyard_meta.by_index_name:
        raise ValueError(f"Box '{box_index_name}' does not exist.")
    
    box_meta = boxyard_meta.by_index_name[box_index_name]
    
    from boxyard._checkout import (
        get_box_checkout_status,
        LocalCheckoutState,
        CheckoutRootUnavailable,
     )
    
    _checkout_status = get_box_checkout_status(config, box_meta)
    if _checkout_status.state == LocalCheckoutState.UNAVAILABLE:
        raise CheckoutRootUnavailable(
            f"Cannot exclude '{box_index_name}': its checkout root "
            f"'{_checkout_status.checkout_root}' is unavailable. Refusing to treat an "
            "unreachable checkout as absent."
        )
    if _checkout_status.state == LocalCheckoutState.EXCLUDED:
        raise ValueError(f"Box '{box_index_name}' is already excluded.")
    if _checkout_status.state != LocalCheckoutState.INCLUDED:
        raise ValueError(
            f"Cannot exclude '{box_index_name}': checkout state is "
            f"{_checkout_status.state.value}. Run `boxyard doctor --no-remote`."
        )
    from boxyard.config import StorageType
    
    if box_meta.get_storage_location_config(config).storage_type == StorageType.LOCAL:
        raise ValueError(
            f"Box '{box_index_name}' in local storage location '{box_meta.storage_location}' cannot be excluded."
        )
    from boxyard._models import BoxMeta
    
    _box_meta_on_disk = BoxMeta.load(config, box_meta.storage_location, box_index_name)
    
    if _box_meta_on_disk.write_owner is not None and (
        _box_meta_on_disk.write_owner == config.machine_name
    ):
        from boxyard.cmds import release_box
    
        try:
            await release_box(
                config_path=config_path, box_index_name=box_index_name, verbose=False
            )
        except Exception as e:
            raise RuntimeError(
                f"Cannot exclude '{box_index_name}': this machine is its write "
                f"owner, and giving that up requires pushing the boxmeta, which "
                f"failed ({e}).\n"
                f"Excluding anyway would leave the box owned by a machine that no "
                f"longer has it, which no machine could then push. Run `boxyard "
                f"release -r '{box_index_name}'` once the remote is reachable, then "
                f"exclude."
            ) from e
        print(
            f"Released write ownership of '{box_index_name}' — excluding a box this "
            f"machine owned would otherwise leave it unpushable everywhere."
        )
    import shutil
    from boxyard._models import BoxPart
    from boxyard.cmds import sync_box
    
    _lock_manager = BoxyardLockManager(config.boxyard_data_path)
    _lock_path = _lock_manager.box_sync_lock_path(box_index_name)
    _lock_manager._ensure_lock_dir(_lock_path)
    _sync_lock = __import__('filelock').FileLock(_lock_path, timeout=0)
    await acquire_lock_async(
        _sync_lock,
        f"box sync ({box_index_name})",
        _lock_path,
        BOX_SYNC_LOCK_TIMEOUT,
    )
    try:
        # Sync any changes before removing locally
        if not skip_sync:
            await sync_box(
                config_path=config_path,
                box_index_name=box_index_name,
                sync_setting=SyncSetting.CAREFUL,
                soft_interruption_enabled=soft_interruption_enabled,
                _skip_lock=True,
            )
    
        # Exclude it - delete local data
        # Retry rmtree to handle macOS race where Finder recreates .DS_Store mid-delete
        import time
        import errno
        _data_path = box_meta.get_local_part_path(config, BoxPart.DATA)
        for _attempt in range(3):
            try:
                shutil.rmtree(_data_path)
                break
            except OSError as e:
                if e.errno == errno.ENOTEMPTY and _attempt < 2:
                    time.sleep(0.1)
                else:
                    raise
        # `missing_ok`, because a restic box need not have a plain `data.rec` at
        # all: a machine that ADOPTED a converted box never wrote one. This used to
        # raise `FileNotFoundError` AFTER the tree had already been deleted and
        # BEFORE the placement was marked excluded, leaving the box in a state where
        # `sync` refused, `exclude` refused again, and nothing could move it.
        #
        # Absence here is a legitimate expected state, not a swallowed error: the
        # record's whole purpose is to describe a local tree, and there is none.
        box_meta.get_local_sync_record_path(config, BoxPart.DATA).unlink(missing_ok=True)
        # Same reasoning for the restic side: this machine's state record claims a
        # local tree at some snapshot, and that claim is now false.
        from boxyard._restic import clear_state
    
        clear_state(config.boxyard_data_path, box_index_name)
        from boxyard._checkout import mark_excluded
        mark_excluded(config, box_meta)
    finally:
        _sync_lock.release()
    
    print(f"Excluded box '{box_meta.name}'")
